package com.example.leavemanagement.contract;
import com.example.leavemanagement.auth.application.AccountUserDetailsService;import com.example.leavemanagement.calendar.api.ManagerCalendarController;import com.example.leavemanagement.calendar.application.ManagerTeamCalendarService;import com.example.leavemanagement.request.api.*;import com.example.leavemanagement.request.application.*;import com.example.leavemanagement.shared.security.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;import org.springframework.context.annotation.Import;import org.springframework.http.MediaType;import org.springframework.security.authentication.AuthenticationManager;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;import java.util.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest({ManagerLeaveRequestController.class,ManagerCalendarController.class,ManagerDashboardController.class}) @Import(SecurityConfiguration.class) class ManagerLeaveApiContractTest { @Autowired MockMvc mvc;@MockitoBean ManagerLeaveRequestQueryService queries;@MockitoBean ManagerDecisionService decisions;@MockitoBean ManagerTeamCalendarService calendars;@MockitoBean ManagerDashboardService dashboards;@MockitoBean CurrentActorProvider actors;@MockitoBean AuthenticationManager authentication;@MockitoBean AccountUserDetailsService users; @Test void expectedVersionIsRequired() throws Exception {var id=UUID.randomUUID();mvc.perform(post("/api/manager/leave-requests/"+id+"/approve").with(user("u").roles("MANAGER")).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{}" )).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("VALIDATION_FAILED"));verifyNoInteractions(decisions);} @Test void managerQueueUsesActorScope() throws Exception {var employee=UUID.randomUUID();when(actors.require()).thenReturn(new CurrentActor(UUID.randomUUID(),employee,null,Set.of("MANAGER"),"Manager"));when(queries.list(employee,0,20,null)).thenReturn(new ManagerLeaveRequestQueryService.PageView(List.of(),0,20,0,0));mvc.perform(get("/api/manager/leave-requests").with(user("u").roles("MANAGER"))).andExpect(status().isOk());verify(queries).list(employee,0,20,null);}}
